#!/usr/bin/env bash
# Shared terminal UX for install.sh — banner, trust copy, spinners. No external deps.
# shellcheck shell=bash

installer_use_color() {
  [[ -z "${NO_COLOR:-}" ]]
}

installer_has_tty() {
  { : >/dev/tty; } 2>/dev/null
}

installer_should_animate() {
  [[ -z "${CI:-}" ]] && installer_use_color && installer_has_tty
}

installer_out() {
  if [[ "${INSTALLER_FRAME_ACTIVE:-0}" == 1 ]]; then
    [[ -z "$*" ]] && return 0
    INSTALLER_STATUS="$(installer_short_path "$*")"
    installer_frame_render
    return 0
  fi
  if installer_has_tty; then printf '%s\n' "$*" >/dev/tty
  else printf '%s\n' "$*"
  fi
}

installer_short_path() {
  local p="$1"
  local home="${HOME:-}"
  if [[ -n "$home" && "$p" == "$home"* ]]; then
    printf '~%s' "${p#"$home"}"
  else
    printf '%s' "$p"
  fi
}

installer_supports_truecolor() {
  case "${COLORTERM:-}" in
    truecolor|24bit) return 0 ;;
  esac
  return 1
}

installer_print_mascot() {
  if [[ -n "${SASS_SETUP_NO_MASCOT:-}" ]] || [[ -n "${NO_COLOR:-}" ]] || [[ -n "${CI:-}" ]]; then
    return 0
  fi
  if ! installer_has_tty; then
    return 0
  fi
  local cols rows w kind f base
  cols="$(tput cols 2>/dev/null || echo 80)"
  rows="$(tput lines 2>/dev/null || echo 24)"
  if [[ "$cols" -lt 40 ]]; then
    return 0
  fi
  w=22
  if [[ "$rows" -lt 14 ]]; then
    return 0
  fi
  if installer_supports_truecolor; then
    kind=truecolor
  else
    kind=256
  fi
  base="${SASS_DIR:-$PWD}/assets/mascot"
  f="${base}/sass-${w}.${kind}.ans"
  if [[ ! -f "$f" ]]; then
    return 0
  fi
  while IFS= read -r line || [[ -n "$line" ]]; do
    printf '  %s\n' "$line" >/dev/tty
  done <"$f"
}

installer_print_banner() {
  if installer_has_tty && [[ "${TERM:-dumb}" != dumb ]] && [[ -z "${CI:-}" && -z "${NO_COLOR:-}" && "${SASS_SETUP_INK:-1}" != 0 ]]; then
    INSTALLER_FRAME_ACTIVE=1
    INSTALLER_STATUS="Ready to install"
    INSTALLER_PROMPT=""
    INSTALLER_TTY_STATE="$(stty -g </dev/tty)"
    stty -echo -icanon isig min 1 time 0 </dev/tty
    printf '\033[?1049h\033[?25l' >/dev/tty
    trap 'installer_frame_exit $?' EXIT
    trap 'exit 130' INT
    trap 'exit 143' TERM
    trap 'INSTALLER_NEEDS_RESIZE=1' WINCH
    installer_frame_render
    return 0
  fi
  if installer_has_tty && installer_should_animate; then
    tput clear >/dev/tty 2>/dev/null || printf '\033[2J\033[H' >/dev/tty
  fi
  installer_print_mascot
  local dim reset
  dim=''
  reset=''
  if installer_should_animate; then
    dim=$'\033[2m'
    reset=$'\033[0m'
  fi
  installer_out "Sass · Discord roast bot"
  local greeting
  greeting="$(installer_pick_greeting)"
  installer_out "  $greeting"
  installer_out "${dim}  No admin password. Nothing outside the folders below.${reset}"
  installer_out ""
}

installer_pick_greeting() {
  local greetings=(
    "Hi — I'll walk you through getting me on your Mac."
    "Ready when you are. I'll ask before I change anything."
    "Let's get me into your server without embarrassing us both."
  )
  printf '%s' "${greetings[RANDOM % ${#greetings[@]}]}"
}

installer_typewriter() {
  local text="$1"
  local delay="${SASS_TYPEWRITER_MS:-18}"
  local i
  printf '  ' >/dev/tty
  for ((i = 0; i < ${#text}; i++)); do
    printf '%s' "${text:i:1}" >/dev/tty
    sleep "$(awk -v d="$delay" 'BEGIN {printf "%.3f", d/1000}')" 2>/dev/null || sleep 0.018
  done
  printf '\n' >/dev/tty
}

installer_trust_preamble() {
  if [[ "${INSTALLER_FRAME_ACTIVE:-0}" == 1 ]]; then
    installer_frame_render
    return 0
  fi
  local branch="${SASS_BRANCH:-main}"
  local source_url="${SASS_INSTALL_SOURCE_URL:-https://github.com/philippsyrov/Sass/blob/${branch}/install.sh}"
  local sass_dir sass_home sass_bin
  sass_dir="$(installer_short_path "${SASS_DIR:-$HOME/Sass}")"
  sass_home="$(installer_short_path "${SASS_HOME:-$HOME/.sass}")"
  sass_bin="$(installer_short_path "${SASS_BIN_DIR:-$HOME/.local/bin}")"
  installer_out "Here's what I'll do:"
  installer_out "  • Put my files in ${sass_dir}"
  if [[ "${SASS_SOURCE_INSTALL:-0}" != 1 ]]; then
    installer_out "  • Download ${SASS_BUNDLE_BYTES:-unknown} bytes; use ${SASS_BUNDLE_UNPACKED_BYTES:-unknown} bytes after extraction"
    installer_out '  • Include the private runtime, database and local memory model'
    installer_out '  • Keep existing configuration and local data'
    installer_out '  • EmbeddingGemma 2: Apache License 2.0'
    installer_out '    https://www.apache.org/licenses/LICENSE-2.0'
    installer_out '  • Terms and third-party notices are included in licenses/'
    installer_out "  • Add the sass command under ${sass_bin}"
    installer_out '  • Run setup; provider API use may cost money'
    return 0
  fi
  installer_out "  • Use my own Node in ${sass_home}/node if yours is older than 20"
  installer_out "  • npm install only inside ${sass_dir}"
  installer_out "  • Add the sass command under ${sass_bin}"
  installer_out "  • Run setup — .env stays in ${sass_dir} (mode 600)"
  installer_out "  • Undo anytime: sass uninstall"
  installer_out ""
  installer_out "Installer source: ${source_url}"
  installer_out ""
}

installer_confirm_continue() {
  if [[ "${SASS_INSTALL_ASSUME_YES:-0}" == "1" ]]; then
    return 0
  fi
  if ! installer_has_tty; then
    installer_out "Run this installer in a terminal, or set SASS_INSTALL_ASSUME_YES=1 for automation."
    return 1
  fi
  local reply
  if [[ "${INSTALLER_FRAME_ACTIVE:-0}" == 1 ]]; then
    stty -echo -icanon -isig min 1 time 0 </dev/tty
    INSTALLER_PROMPT='Continue? Enter/y=yes, n=quit'
    installer_frame_render
    while :; do
      # Preserve Enter as a byte; an interrupted empty read must never approve.
      if IFS= read -r -s -d '' -n 1 -t 1 reply </dev/tty; then
        :
      else
        # A resize can interrupt Bash 3.2 read with status 1. It is not consent or refusal.
        if installer_has_tty; then
          installer_frame_render
          continue
        fi
        return 1
      fi
      if [[ "${INSTALLER_NEEDS_RESIZE:-0}" == 1 ]]; then installer_frame_render; fi
      case "$reply" in
        y|Y|$'\n'|$'\r')
          if [[ "$INSTALLER_COLS" -lt 80 || "$INSTALLER_ROWS" -lt 24 ]]; then
            INSTALLER_STATUS='Resize the window to read the plan before continuing.'
            installer_frame_render
            continue
          fi
          if [[ "${SASS_SOURCE_INSTALL:-0}" != 1 ]] && [[ "$(installer_short_path "$SASS_DIR" | fold -s -w "$((INSTALLER_COLS - 49))" | wc -l | tr -d ' ')" -gt 3 ]]; then
            INSTALLER_STATUS='Widen the window to read the full install path.'
            installer_frame_render
            continue
          fi
          INSTALLER_PROMPT=""
          stty "$INSTALLER_TTY_STATE" </dev/tty
          return 0 ;;
        $'\003') exit 130 ;;
        n|N) INSTALLER_STATUS='Stopped. Nothing was changed.'; return 1 ;;
        *) installer_frame_render ;;
      esac
    done
  fi
  printf 'Continue? (Enter = yes, n = quit) ' >/dev/tty
  read -r reply </dev/tty || return 1
  reply="${reply:-y}"
  case "$reply" in
    y|Y|yes|YES|'') return 0 ;;
    *) installer_out "Stopped — nothing was changed."; return 1 ;;
  esac
}

INSTALLER_SPINNER_PID=
INSTALLER_SPINNER_MSG=

installer_spinner_start() {
  if [[ "${INSTALLER_FRAME_ACTIVE:-0}" == 1 ]]; then
    installer_out "$1"
    return 0
  fi
  INSTALLER_SPINNER_MSG="$1"
  if ! installer_should_animate; then
    installer_out "  … $1"
    return 0
  fi
  local frames='⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏'
  (
    i=0
    while true; do
      c="${frames:i%${#frames}:1}"
      printf '\r  %s %s' "$c" "$INSTALLER_SPINNER_MSG" >/dev/tty
      sleep 0.08
      i=$((i + 1))
    done
  ) &
  INSTALLER_SPINNER_PID=$!
}

installer_spinner_ok() {
  if [[ "${INSTALLER_FRAME_ACTIVE:-0}" == 1 ]]; then
    installer_out "Done: ${1:-$INSTALLER_SPINNER_MSG}"
    return 0
  fi
  local msg="${1:-$INSTALLER_SPINNER_MSG}"
  if [[ -n "${INSTALLER_SPINNER_PID:-}" ]]; then
    kill "$INSTALLER_SPINNER_PID" 2>/dev/null || true
    wait "$INSTALLER_SPINNER_PID" 2>/dev/null || true
    INSTALLER_SPINNER_PID=
  fi
  if installer_should_animate; then
    printf '\r  \033[32m✓\033[0m %s\n' "$msg" >/dev/tty
  else
    installer_out "  ✓ $msg"
  fi
}

installer_spinner_fail() {
  if [[ "${INSTALLER_FRAME_ACTIVE:-0}" == 1 ]]; then
    installer_out "Failed: $1"
    return 0
  fi
  local msg="${1:-$INSTALLER_SPINNER_MSG}"
  if [[ -n "${INSTALLER_SPINNER_PID:-}" ]]; then
    kill "$INSTALLER_SPINNER_PID" 2>/dev/null || true
    wait "$INSTALLER_SPINNER_PID" 2>/dev/null || true
    INSTALLER_SPINNER_PID=
  fi
  if installer_should_animate; then
    printf '\r  \033[31m✗\033[0m %s\n' "$msg" >/dev/tty
  else
    installer_out "  ✗ $msg"
  fi
}

# Bundled source artwork, available before cloning the repository.
installer_bootstrap_art() {
  if [[ "${SASS_COLOR_DEPTH:-truecolor}" == 256 ]]; then
    installer_bootstrap_art_256
  else
    installer_bootstrap_art_truecolor
  fi
}

