installer_frame_line() {
  local row="$1" col="$2" text="$3" width
  width=$((INSTALLER_COLS - col))
  [[ "$row" -lt "$INSTALLER_ROWS" && "$width" -gt 0 ]] || return 0
  printf '\033[%s;%sH%s' "$row" "$col" "${text:0:width}" >/dev/tty
}

installer_frame_wrap() {
  local row="$1" col="$2" limit="$3" text="$4" line width count=0
  width=$((INSTALLER_COLS - col))
  [[ "$width" -gt 0 ]] || return 0
  while IFS= read -r line; do
    [[ "$count" -lt "$limit" ]] || break
    installer_frame_line "$((row + count))" "$col" "$line"
    count=$((count + 1))
  done < <(printf '%s\n' "$text" | fold -s -w "$width")
}

installer_frame_render() {
  [[ "${INSTALLER_FRAME_ACTIVE:-0}" == 1 ]] || return 0
  INSTALLER_NEEDS_RESIZE=0
  local size
  size="$(stty size </dev/tty 2>/dev/null || echo '24 80')"
  IFS=' ' read -r INSTALLER_ROWS INSTALLER_COLS <<<"$size"
  printf '\033[H\033[2J' >/dev/tty
  local row=1 line
  while IFS= read -r line; do
    [[ "$row" -lt "$INSTALLER_ROWS" && "$INSTALLER_COLS" -ge 47 ]] || break
    printf '\033[%s;2H%s' "$row" "$line" >/dev/tty
    row=$((row + 1))
  done < <(installer_bootstrap_art)
  local text_col=49
  if [[ "$INSTALLER_COLS" -lt 80 ]]; then
    installer_frame_line 1 2 'Sass · Discord roast bot'
    installer_frame_line $((INSTALLER_ROWS - 4)) 2 "${INSTALLER_STATUS:-Ready to install}"
    installer_frame_line $((INSTALLER_ROWS - 3)) 2 'Resize to 80 columns by 24 rows to see details.'
    installer_frame_line $((INSTALLER_ROWS - 2)) 2 "${INSTALLER_PROMPT:-Ctrl+C to cancel}"
    return 0
  fi
  installer_frame_line 1 "$text_col" 'Sass · Discord roast bot'
  installer_frame_line 3 "$text_col" 'One install; then connect Sass.'
  if [[ "${SASS_SOURCE_INSTALL:-0}" != 1 ]]; then
    installer_frame_line 5 "$text_col" "Download: ${SASS_BUNDLE_BYTES:-checking} bytes"
    installer_frame_line 6 "$text_col" "On disk: ${SASS_BUNDLE_UNPACKED_BYTES:-checking} bytes"
    installer_frame_line 8 "$text_col" 'Runtime, database, memory model.'
    installer_frame_line 9 "$text_col" 'Keep settings and local data.'
    installer_frame_line 10 "$text_col" 'EmbeddingGemma 2'
    installer_frame_line 11 "$text_col" 'Apache License 2.0'
    installer_frame_line 12 "$text_col" 'apache.org/licenses/LICENSE-2.0'
    installer_frame_line 13 "$text_col" 'Read the bundled license.'
    installer_frame_line 14 "$text_col" 'Preserve upstream notices.'
    installer_frame_line 15 "$text_col" 'Notices included in licenses/.'
    installer_frame_line 16 "$text_col" 'Files:'
    installer_frame_wrap 17 "$text_col" 4 "$(installer_short_path "$SASS_DIR")"
    installer_frame_wrap 21 "$text_col" 2 "${INSTALLER_ERROR:-${INSTALLER_STATUS:-Preparing setup}}"
    installer_frame_line $((INSTALLER_ROWS - 1)) "$text_col" "${INSTALLER_PROMPT:-Ctrl+C to cancel}"
    return 0
  fi
  installer_frame_line 5 "$text_col" "Files: $(installer_short_path "$SASS_DIR")"
  installer_frame_line 6 "$text_col" "Node: $(installer_short_path "$SASS_HOME")/node"
  installer_frame_line 7 "$text_col" 'Only if Node is missing or old.'
  installer_frame_line 9 "$text_col" 'Dependencies in the Sass folder.'
  installer_frame_line 10 "$text_col" "Command: $(installer_short_path "$SASS_BIN_DIR")/sass"
  installer_frame_line 12 "$text_col" '.env stays in the Sass folder.'
  installer_frame_line 13 "$text_col" 'Secrets hidden; file mode 600.'
  installer_frame_line 15 "$text_col" 'No admin password.'
  installer_frame_line 16 "$text_col" 'Remove: sass uninstall'
  installer_frame_line 18 "$text_col" 'Source: github.com/'
  installer_frame_line 19 "$text_col" 'philippsyrov/Sass'
  installer_frame_line 21 "$text_col" "${INSTALLER_STATUS:-Preparing setup}"
  if [[ -n "${INSTALLER_ERROR:-}" ]]; then
    installer_frame_line 22 "$text_col" "$INSTALLER_ERROR"
  fi
  if [[ "$INSTALLER_ROWS" -lt 24 ]]; then
    installer_frame_line $((INSTALLER_ROWS - 3)) "$text_col" 'Resize to 80 columns by 24 rows.'
  fi
  installer_frame_line $((INSTALLER_ROWS - 1)) "$text_col" "${INSTALLER_PROMPT:-Ctrl+C to cancel}"

}

installer_task() {
  if [[ "${INSTALLER_FRAME_ACTIVE:-0}" == 1 ]]; then
    if [[ -z "${INSTALLER_LOG:-}" ]]; then
      mkdir -p "$SASS_HOME"
      INSTALLER_LOG="$(mktemp "$SASS_HOME/install.XXXXXX")"
      chmod 600 "$INSTALLER_LOG"
    fi
    "$@" >>"$INSTALLER_LOG" 2>&1
  else
    "$@"
  fi
}

installer_frame_exit() {
  local code="$1" reply
  trap - EXIT INT TERM WINCH
  if [[ "${INSTALLER_FRAME_ACTIVE:-0}" == 1 ]]; then
    if [[ "$code" -ne 0 && "$code" -ne 130 && "$code" -ne 143 ]]; then
      INSTALLER_ERROR="${INSTALLER_STATUS:-Unknown error}"
      [[ -z "${INSTALLER_LOG:-}" ]] || printf '%s\n' "$INSTALLER_ERROR" >>"$INSTALLER_LOG"
      INSTALLER_STATUS="Install stopped (code $code). Run the same curl command to retry."
    fi
    if [[ "$code" -ne 130 && "$code" -ne 143 && "${INSTALLER_SKIP_CLOSE:-0}" != 1 ]]; then
      INSTALLER_PROMPT='Press Enter to close'
      installer_frame_render
      stty -echo -icanon -isig min 1 time 0 </dev/tty
      IFS= read -r -s -n 1 reply </dev/tty || true
    fi
    stty "$INSTALLER_TTY_STATE" </dev/tty 2>/dev/null || true
    printf '\033[0m\033[?25h\033[?1049l' >/dev/tty
    INSTALLER_FRAME_ACTIVE=0
    if [[ -n "${INSTALLER_LOG:-}" && "$code" -ne 0 ]]; then
      printf 'Sass install stopped. Private log: %s\n' "$(installer_short_path "$INSTALLER_LOG")" >/dev/tty
    fi
  fi
  [[ -z "${INSTALLER_UI_TEMP:-}" ]] || rm -f "$INSTALLER_UI_TEMP"
  return "$code"
}
